INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (1, N'Mai', N'Tâm Lý, Tình Cảm', 131, '2026-02-10 00:00:00.000', '2026-12-30 00:00:00.000', N'Trấn Thành', N'Phương Anh Đào, Tuấn Trần, Trấn Thành, Hồng Đào', N'Mai xoay quanh cuộc đời của người phụ nữ cùng tên. Số phận đưa đẩy cô gặp gỡ Dương - chàng trai trẻ tuổi, đào hoa, mở ra mối tình vừa ngọt ngào vừa đầy thử thách.', N'https://images.unsplash.com/photo-1536440136628-849c177e76a1?w=500', N'https://www.youtube.com/watch?v=HKb0z8kYw3c', N'T18', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (2, N'Dune: Hành Tinh Cát 2', N'Khoa Học Viễn Tưởng, Phiêu Lưu', 166, '2026-03-01 00:00:00.000', '2026-12-30 00:00:00.000', N'Denis Villeneuve', N'Timothée Chalamet, Zendaya, Rebecca Ferguson', N'Hành trình của Paul Atreides khi anh hợp nhất với Chani và người Fremen để trả thù những kẻ đã hủy hoại gia đình mình.', N'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=500', N'https://www.youtube.com/watch?v=Way9Dexny3w', N'T16', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (3, N'Godzilla x Kong: Đế Chế Mới', N'Hành Động, Viễn Tưởng', 115, '2026-03-29 00:00:00.000', '2026-12-30 00:00:00.000', N'Adam Wingard', N'Rebecca Hall, Brian Tyree Henry, Dan Stevens', N'Hai thực thể hùng mạnh Godzilla và Kong phải hợp sức chống lại mối hiểm họa khổng lồ tiềm ẩn sâu trong lòng Trái Đất.', N'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?w=500', N'https://www.youtube.com/watch?v=qqrpMRDuPfc', N'T13', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (4, N'Kung Fu Panda 4', N'Hoạt Hình, Hài Hước', 94, '2026-03-08 00:00:00.000', '2026-12-30 00:00:00.000', N'Mike Mitchell', N'Jack Black, Awkwafina, Viola Davis', N'Po chuẩn bị trở thành Thủ lĩnh Tinh thần của Thung lũng Bình Yên nhưng phải đối đầu với phù thủy Tắc Kè Hoa có khả năng biến hình nguy hiểm.', N'https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=500', N'https://www.youtube.com/watch?v=_inKs4eeHiI', N'P', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (5, N'Lật Mặt 7: Một Điều Ước', N'Gia Đình, Tâm Lý', 138, '2026-04-26 00:00:00.000', '2026-12-30 00:00:00.000', N'Lý Hải', N'Thanh Hiền, Trương Minh Cường, Đinh Y Nhung, Quách Ngọc Tuyên', N'Câu chuyện cảm động về gia đình bà Hai và 5 người con, phản ánh tình mẫu tử thiêng liêng và thực trạng đạo hiếu trong xã hội hiện đại.', N'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=500', N'https://www.youtube.com/watch?v=d9MyW72ELq0', N'K', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (6, N'Deadpool & Wolverine', N'Hành Động, Siêu Anh Hùng, Hài Hước', 127, '2026-07-26 00:00:00.000', '2026-12-30 00:00:00.000', N'Shawn Levy', N'Ryan Reynolds, Hugh Jackman, Emma Corrin', N'Deadpool và Wolverine bất đắc dĩ hợp tác cùng Cơ quan Quản lý Phương sai Thời gian (TVA) để bảo vệ vũ trụ.', N'https://images.unsplash.com/photo-1563089145-599997674d42?w=500', N'https://www.youtube.com/watch?v=73_1biulkYk', N'T18', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (7, N'Exhuma: Quật Mộ Trùng Ma', N'Kinh Dị, Bí Ẩn', 134, '2026-03-15 00:00:00.000', '2026-12-30 00:00:00.000', N'Jang Jae-hyun', N'Choi Min-sik, Kim Go-eun, Lee Do-hyun, Yoo Hae-jin', N'Quá trình khai quật một ngôi mộ bí ẩn đem lại hậu quả kinh hoàng khi giải phóng thế lực hắc ám cổ xưa.', N'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?w=500', N'https://www.youtube.com/watch?v=73_1biulkYk', N'T18', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (8, N'Kẻ Trộm Mặt Trăng 4 (Despicable Me 4)', N'Hoạt Hình, Hài Hước, Gia Đình', 95, '2026-07-05 00:00:00.000', '2026-12-30 00:00:00.000', N'Chris Renaud', N'Steve Carell, Kristen Wiig, Will Ferrell, Sofia Vergara', N'Gru và gia đình bước vào cuộc sống mới cùng thành viên nhí Gru Jr., nhưng sớm đối mặt với kẻ thù mới nguy hiểm.', N'https://images.unsplash.com/photo-1534447677768-be436bb09401?w=500', N'https://www.youtube.com/watch?v=qQlr9-rF32A', N'P', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (9, N'Furiosa: Câu Chuyện Từ Max Điên', N'Hành Động, Viễn Tưởng, Phiêu Lưu', 148, '2026-05-24 00:00:00.000', '2026-12-30 00:00:00.000', N'George Miller', N'Anya Taylor-Joy, Chris Hemsworth, Tom Burke', N'Khi thế giới sụp đổ, Furiosa trẻ tuổi bị bắt cóc khỏi Nơi Xanh và rơi vào tay Băng Đảng Xe Máy Lãnh chúa Dementus.', N'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=500', N'https://www.youtube.com/watch?v=XJMuhwVlca4', N'T18', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (10, N'Hành Tinh Khỉ: Vương Quốc Mới', N'Khoa Học Viễn Tưởng, Hành Động', 145, '2026-05-10 00:00:00.000', '2026-12-30 00:00:00.000', N'Wes Ball', N'Owen Teague, Freya Allan, Kevin Durand, Peter Macon', N'Nhiều thế hệ sau thời kỳ của Caesar, loài khỉ trở thành giống loài thống trị hài hòa cùng thiên nhiên.', N'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?w=500', N'https://www.youtube.com/watch?v=XtFI7SNtVpY', N'T13', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (11, N'Vây Hãm: Kẻ Trừng Phạt (The Roundup 4)', N'Hành Động, Tội Phạm, Hài Hước', 109, '2026-04-26 00:00:00.000', '2026-12-30 00:00:00.000', N'Heo Myeong-haeng', N'Ma Dong-seok, Kim Mu-yeol, Park Ji-hwan, Lee Dong-hwi', N'Thanh tra Ma Seok-do tham gia đội điều tra không gian mạng để triệt phá tổ chức cờ bạc trực tuyến quy mô quốc tế.', N'https://images.unsplash.com/photo-1563089145-599997674d42?w=500', N'https://www.youtube.com/watch?v=s1X9e_m394g', N'T18', N'NOW_SHOWING');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (12, N'Transformers: Một (Transformers One)', N'Hoạt Hình, Hành Động, Viễn Tưởng', 104, '2026-12-15 00:00:00.000', '2027-02-28 00:00:00.000', N'Josh Cooley', N'Chris Hemsworth, Brian Tyree Henry, Scarlett Johansson', N'Câu chuyện khởi nguồn chưa từng kể về mối quan hệ huynh đệ giữa Optimus Prime và Megatron.', N'https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=500', N'https://www.youtube.com/watch?v=u2NuUVbfzmA', N'P', N'COMING_SOON');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (13, N'Moana 2: Hành Trình Mới', N'Hoạt Hình, Âm Nhạc, Phiêu Lưu', 100, '2026-11-27 00:00:00.000', '2027-02-15 00:00:00.000', N'David G. Derrick Jr.', N'Auli''i Cravalho, Dwayne Johnson, Alan Tudyk', N'Sau khi nhận được lời kêu gọi bất ngờ từ tổ tiên, Moana cùng Maui và thủy thủ đoàn mới bắt đầu cuộc thám hiểm.', N'https://images.unsplash.com/photo-1536440136628-849c177e76a1?w=500', N'https://www.youtube.com/watch?v=hDZ7y8RP5HE', N'P', N'COMING_SOON');
INSERT INTO Movies (movie_id, title, genre, duration, release_date, end_date, director, cast, description, poster_url, trailer_url, age_rating, status) VALUES (14, N'Joker: Điên Có Đôi (Folie à Deux)', N'Tâm Lý, Tội Phạm, Ca Nhạc', 138, '2026-12-04 00:00:00.000', '2027-02-20 00:00:00.000', N'Todd Phillips', N'Joaquin Phoenix, Lady Gaga, Brendan Gleeson', N'Arthur Fleck bị giam giữ tại Arkham chờ ngày xét xử. Tại đây, anh gặp gỡ tình yêu định mệnh Harley Quinn.', N'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=500', N'https://www.youtube.com/watch?v=_OKAwz2NiJs', N'T18', N'COMING_SOON');
