USE master;
GO
IF NOT EXISTS (SELECT * FROM sys.databases WHERE name = 'CinemaDB')
BEGIN
    CREATE DATABASE CinemaDB COLLATE Vietnamese_CI_AS;
END
GO
USE CinemaDB;
GO

IF OBJECT_ID('Tickets', 'U') IS NOT NULL DROP TABLE Tickets;
IF OBJECT_ID('Bookings', 'U') IS NOT NULL DROP TABLE Bookings;
IF OBJECT_ID('MovieTranslations', 'U') IS NOT NULL DROP TABLE MovieTranslations;
IF OBJECT_ID('Showtimes', 'U') IS NOT NULL DROP TABLE Showtimes;
IF OBJECT_ID('Seats', 'U') IS NOT NULL DROP TABLE Seats;
IF OBJECT_ID('Rooms', 'U') IS NOT NULL DROP TABLE Rooms;
IF OBJECT_ID('Movies', 'U') IS NOT NULL DROP TABLE Movies;
IF OBJECT_ID('Languages', 'U') IS NOT NULL DROP TABLE Languages;
IF OBJECT_ID('SystemSettings', 'U') IS NOT NULL DROP TABLE SystemSettings;
IF OBJECT_ID('Users', 'U') IS NOT NULL DROP TABLE Users;
CREATE TABLE Users (user_id INT IDENTITY(1,1) PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, full_name NVARCHAR(100) NOT NULL, email VARCHAR(100) UNIQUE NOT NULL, phone VARCHAR(20), role VARCHAR(20) DEFAULT 'CUSTOMER', status BIT DEFAULT 1, created_at DATETIME DEFAULT GETDATE());
CREATE TABLE SystemSettings (setting_key VARCHAR(50) PRIMARY KEY, setting_value NVARCHAR(MAX), updated_at DATETIME DEFAULT GETDATE());
CREATE TABLE Languages (lang_code VARCHAR(10) PRIMARY KEY, country_name NVARCHAR(100) NOT NULL, flag_url VARCHAR(255) NOT NULL, is_active BIT DEFAULT 1, is_default BIT DEFAULT 0, created_at DATETIME DEFAULT GETDATE());
CREATE TABLE Movies (movie_id INT IDENTITY(1,1) PRIMARY KEY, title NVARCHAR(200) NOT NULL, genre NVARCHAR(100) NOT NULL, duration INT NOT NULL, release_date DATE NOT NULL, end_date DATE, director NVARCHAR(100), cast NVARCHAR(500), description NVARCHAR(MAX), poster_url VARCHAR(500), trailer_url VARCHAR(500), age_rating VARCHAR(10) DEFAULT 'P', status VARCHAR(20) DEFAULT 'COMING_SOON');
CREATE TABLE MovieTranslations (translation_id INT IDENTITY(1,1) PRIMARY KEY, movie_id INT NOT NULL FOREIGN KEY REFERENCES Movies(movie_id) ON DELETE CASCADE, lang_code VARCHAR(10) NOT NULL, title NVARCHAR(200) NOT NULL, genre NVARCHAR(100), description NVARCHAR(MAX), director NVARCHAR(100), cast NVARCHAR(500), created_at DATETIME DEFAULT GETDATE(), CONSTRAINT UQ_Movie_Lang UNIQUE (movie_id, lang_code));
CREATE TABLE Rooms (room_id INT IDENTITY(1,1) PRIMARY KEY, room_name NVARCHAR(100) NOT NULL, room_type VARCHAR(20) DEFAULT '2D', total_rows INT NOT NULL, total_cols INT NOT NULL, status BIT DEFAULT 1);
CREATE TABLE Seats (seat_id INT IDENTITY(1,1) PRIMARY KEY, room_id INT FOREIGN KEY REFERENCES Rooms(room_id) ON DELETE CASCADE, seat_row CHAR(2) NOT NULL, seat_number INT NOT NULL, seat_type VARCHAR(20) DEFAULT 'STANDARD', price_modifier DECIMAL(10,2) DEFAULT 0.00, CONSTRAINT UQ_Room_Seat UNIQUE (room_id, seat_row, seat_number));
CREATE TABLE Showtimes (showtime_id INT IDENTITY(1,1) PRIMARY KEY, movie_id INT FOREIGN KEY REFERENCES Movies(movie_id) ON DELETE CASCADE, room_id INT FOREIGN KEY REFERENCES Rooms(room_id) ON DELETE CASCADE, show_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, base_price DECIMAL(10,2) NOT NULL, status VARCHAR(20) DEFAULT 'OPEN');
CREATE TABLE Bookings (booking_id INT IDENTITY(1,1) PRIMARY KEY, user_id INT FOREIGN KEY REFERENCES Users(user_id) ON DELETE CASCADE, showtime_id INT FOREIGN KEY REFERENCES Showtimes(showtime_id), booking_code VARCHAR(20) UNIQUE NOT NULL, total_amount DECIMAL(12,2) NOT NULL, payment_status VARCHAR(20) DEFAULT 'PENDING', payment_method VARCHAR(20), booking_time DATETIME DEFAULT GETDATE());
CREATE TABLE Tickets (ticket_id INT IDENTITY(1,1) PRIMARY KEY, booking_id INT FOREIGN KEY REFERENCES Bookings(booking_id) ON DELETE CASCADE, seat_id INT FOREIGN KEY REFERENCES Seats(seat_id), price DECIMAL(10,2) NOT NULL);
GO

